INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7dc18a7c-f96b-41c1-8ac6-60b3db7444e4', 'c3c3c3c3-3030-4000-8000-000000000003', 20, 'Dia 20 — Soltar', 'Semana 3: Discernir', '{"pch": "Lan\u00e7a sobre o Senhor o teu fardo\u2026 Pensamentos obsessivos s\u00e3o fardos que n\u00e3o te pertencem.", "verse": "Sl 55,22", "lectio": "Leia Sl 55,16-23. Deus sustenta.", "practice": "Escreva o pensamento que te atormenta num papel. Depois, rasgue-o como ato simb\u00f3lico.", "question": "Que pensamento voc\u00ea precisa parar de carregar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;